<script setup>
import {computed,ref} from 'vue'
import SimulationControls from './SimulationControls.vue'
import {convertCnf,cnfText} from '../services/propositional-logic.mjs'
const input=ref('P <-> (Q & R)'),source=ref(input.value),step=ref(0),error=ref('')
const data=computed(()=>convertCnf(source.value)),current=computed(()=>data.value.steps[step.value])
function apply(){try{convertCnf(input.value);source.value=input.value;step.value=0;error.value=''}catch(e){error.value=e.message}}
</script>
<template><figure class="lab prop-cnf" aria-label="Chuyển công thức logic sang CNF và kiểm tra tương đương"><label>Công thức<input v-model="input" type="text" spellcheck="false"/></label><button type="button" @click="apply">Chuyển đổi</button><p v-if="error" role="alert">{{ error }}</p><SimulationControls v-model="step" :max="data.steps.length-1" :reset-key="source"/><p class="cnf-stage" role="status"><strong>{{ current.label }}</strong><span>{{ current.text }}</span></p><p>Phép chuyển này giữ tương đương trên cùng các ký hiệu, không thêm biến phụ. Các bước phân phối có thể làm số clause tăng nhanh, nên bộ xem chỉ nhận tối đa sáu ký hiệu và ví dụ nhỏ.</p><details><summary>Clause cuối và bảng kiểm chứng</summary><p>{{ data.clauses.length===0?'Tập clause rỗng biểu diễn Đúng.':cnfText(data.clauses) }}</p><ol><li v-for="(c,i) in data.clauses" :key="i">Clause {{ i+1 }}: {{ c.length?c.map(x=>x.replace('!','¬')).join(' ∨ '):'□ (Sai)' }}</li></ol><p>Đối chiếu {{ data.rows.length }} phép gán: {{ data.equivalent?'Hai công thức luôn cùng giá trị.':'Có hàng khác giá trị.' }}</p><ul><li v-for="(r,i) in data.rows" :key="i">{{ Object.entries(r.model).map(([k,v])=>k+'='+Number(v)).join(', ') }} · Trước {{ Number(r.before) }} · Sau {{ Number(r.after) }}</li></ul></details></figure></template>
<style scoped>
.prop-cnf{min-width:0}.prop-cnf label{display:grid;gap:6px}.prop-cnf :is(input,button){min-height:44px;border:1px solid var(--control);border-radius:var(--radius);padding:8px;max-width:100%;box-sizing:border-box;background:var(--paper);color:var(--ink);font:var(--fs-small)/1.7 var(--font-ui)}.prop-cnf input{width:100%;font-family:var(--font-code)}.prop-cnf button{cursor:pointer;margin-top:8px}.prop-cnf :is(button,input):focus-visible{outline:3px solid var(--tim);outline-offset:3px}.cnf-stage{display:grid;gap:12px;border-left:3px solid var(--tim);padding:12px;background:var(--tim-soft)}.cnf-stage span{font-family:var(--font-code);overflow-wrap:anywhere;line-height:1.9}.prop-cnf :is(p,li,summary){font:var(--fs-small)/1.7 var(--font-ui);overflow-wrap:anywhere}.prop-cnf details{margin-top:16px}.prop-cnf summary{cursor:pointer;min-height:44px}@media(max-width:600px){.prop-cnf{padding:12px}}
</style>
